def priority(task, state, k=1.0, m=1.5, r=2.0, s=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / est * math.exp(-slack / (k * mean_est))
    if state.now <= task.due:
        value_frac = 1.0
    elif state.now >= task.due + 2.0 * est:
        value_frac = 0.0
    else:
        value_frac = 1.0 - (state.now - task.due) / (2.0 * est)
    loss_risk = 1.0 + r * (1.0 - value_frac)
    congestion = state.queue_work / max(state.capacity * mean_est, 1e-6)
    size_penalty = 1.0 / (1.0 + s * math.log1p(congestion) * est / mean_est)
    return tier * atc * loss_risk * size_penalty  # tuned (k=0.335,m=2.91,r=0.685,s=0.36)

