import math
def priority(task, state, k=1.5, m=2.0, q_hi=0.6, q_lo=0.25):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    load = state.queue_work / max(state.capacity, 1e-6)
    if load >= q_hi:
        kk = k * 0.5
    elif load <= q_lo:
        kk = k * 2.0
    else:
        kk = k
    return tier * task.weight / est * math.exp(-slack / (kk * max(state.mean_est, 1e-6)))

def priority(task, state):
    # Value-density with SLA decay awareness
    # Estimate value decay rate: weight lost per unit time after due
    decay_window = 2.0 * max(task.estimated_runtime, 1e-6)
    # If already past due, value is decaying; if not, full weight still available
    if state.now >= task.due:
        remaining_value = max(0.0, 1.0 - (state.now - task.due) / decay_window)
    else:
        remaining_value = 1.0
    # Priority = current value density (value per core-second)
    return (task.weight * remaining_value) / max(task.estimated_runtime * task.resource_need, 1e-6)
